import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useBottomTabsContextValue } from '../../context'
import { getPartnerToken } from '../actions'

export const useBottomTabsServiceCall = (actionsCall = () => {}) => {
  const [bottomTabsState, dispatch] = useBottomTabsContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [bottomTabsState, request]
}

export const useGetPartnerToken = () => {
  return useBottomTabsServiceCall(getPartnerToken)
}
