import { withRouter } from 'react-router-dom'
import { BottomTabsWrapper } from './index.style'
import CustomText from '../../CustomText'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { ANDROID_BRIDGE } from '../../../bridges/android'
import { useCallback, useEffect } from 'react'
import { useGlobalContextValue } from '../../../contextProvider/GlobalContext'
import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { useGetPartnerToken } from '../state/hooks/useBottomTabsState'
import { get } from 'lodash'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import { PARTNER_CODE } from '../../../constants/appConstants'
import { gTagOnBottomTabsClick } from '../../../tagManager'
import { getVisibleBottomTabs } from './helpers'

function BottomTabsContainer(props) {
  const { location, activeTab, history, showHideLoader } = props
  const [{ getAgentDetailData, isGojekAgent, isInternalAgent, isStaffAgent }] =
    useGlobalContextValue()
  const [{ GET_PARTNER_TOKEN_ERROR, getPartnerTokenStatus = '' }, dispatchError] =
    useErrorContextValue()

  const [{ getPartnerTokenData = {} }, getPartnerTokenRequest] = useGetPartnerToken()
  useEffect(() => {
    const accessToken = getPartnerTokenData.access_token
    if (
      getPartnerTokenStatus === 'success' &&
      accessToken &&
      !get(getAgentDetailData, 'elearning_details_page_enable', true)
    ) {
      const prosparkUrl = `${process.env.REACT_APP_ELMS_URL}?access_token=${accessToken}`
      dispatchError(
        resetError({
          getPartnerTokenStatus: '',
        })
      )
      window.open(prosparkUrl, '_self')
      showHideLoader(false)
    } else if (GET_PARTNER_TOKEN_ERROR && getPartnerTokenStatus) {
      showHideLoader(false)
      NotificationManager.error(getPartnerTokenStatus)
      dispatchError(
        resetError({
          getPartnerTokenStatus: '',
          GET_PARTNER_TOKEN_ERROR: false,
        })
      )
    }
  }, [
    getPartnerTokenStatus,
    dispatchError,
    GET_PARTNER_TOKEN_ERROR,
    showHideLoader,
    getPartnerTokenData.access_token,
    getAgentDetailData,
  ])

  const handleRedir = useCallback(
    (pathname, name) => {
      gTagOnBottomTabsClick(name)
      if (name === 'elearning' && !get(getAgentDetailData, 'elearning_details_page_enable', true)) {
        showHideLoader(true)
        getPartnerTokenRequest({ partner_code: PARTNER_CODE.PROSPARK })
      } else {
        history.push(pathname)
      }
    },
    [history, getAgentDetailData, getPartnerTokenRequest, showHideLoader]
  )

  const renderTab = useCallback(
    ({ pathname, Icon, name, label }) => {
      return (
        <div
          key={name}
          className="tabs"
          onClick={() => handleRedir(pathname, name)}
          id={`bottom-tab-${activeTab || name}`}
        >
          <Icon
            className={
              location.pathname.startsWith(pathname) || activeTab === name
                ? 'active-svg'
                : 'transparent'
            }
          />
          <CustomText
            fontSize="0.8em"
            color={
              location.pathname.startsWith(pathname) || activeTab === name
                ? AgentColorPallette.black
                : AgentColorPallette.fontGrey
            }
            weight={500}
          >
            {label}
          </CustomText>
        </div>
      )
    },
    [location, activeTab, handleRedir]
  )

  let lmsHostname = ''
  if (process.env.REACT_APP_ELMS_URL) {
    lmsHostname = new URL(process.env.REACT_APP_ELMS_URL).hostname
  }
  const showLms = process.env.REACT_APP_ELMS_ENABLE === 'true' && (!isGojekAgent || isInternalAgent)
  if (ANDROID_BRIDGE.whiteListDomain && showLms) {
    ANDROID_BRIDGE.whiteListDomain(lmsHostname)
  }

  const visibleTabs = getVisibleBottomTabs({
    isStaffAgent,
    agentData: getAgentDetailData,
    showLms,
  })

  return (
    <BottomTabsWrapper id="dashboard3" tabPosition={props.tabPosition}>
      {visibleTabs.map(renderTab)}
      <NotificationContainer />
    </BottomTabsWrapper>
  )
}

export default withRouter(BottomTabsContainer)
