import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

// this is the context used by the all pages
export const BottomTabsContext = createContext()

// provider provide the update context value
export const BottomTabsContextProvider = (props) => {
  // use reducer provides the initial state and dispatch function
  // to all nested children [state, dispatch]

  return (
    <BottomTabsContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </BottomTabsContext.Provider>
  )
}

// use to read the value from the global state
export const useBottomTabsContextValue = () => useContext(BottomTabsContext)
