import { BOTTOM_TAB_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case BOTTOM_TAB_ACTIONS.GET_PARTNER_TOKEN:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
