import { ReactComponent as HomeSvg } from '../../../images/home.svg'
import { ReactComponent as TransactionsSvg } from '../../../images/file.svg'
import { ReactComponent as WalletSvg } from '../../../images/wallet.svg'
import { ReactComponent as LearningSvg } from '../../../images/learning.svg'
import { ReactComponent as AgentSvg } from '../../../images/agent.svg'
import { LANG_STRINGS } from '../../../lang'
import { checkIsLvAdmin } from '../../../helpers/checkAgentTags'

const BOTTOM_TABS = [
  {
    name: 'dashboard',
    pathname: '/dashboard',
    Icon: HomeSvg,
    label: LANG_STRINGS.home,
  },
  {
    name: 'transaction',
    pathname: '/transactions',
    Icon: TransactionsSvg,
    label: LANG_STRINGS.transaction1,
    isVisible: ({ isStaffAgent, agentData }) => !isStaffAgent && !checkIsLvAdmin(agentData),
  },
  {
    name: 'balance',
    pathname: '/balance',
    Icon: WalletSvg,
    label: LANG_STRINGS.balance,
    isVisible: ({ isStaffAgent, agentData }) => !isStaffAgent && !checkIsLvAdmin(agentData),
  },
  {
    name: 'elearning',
    pathname: '/elearning/intro',
    Icon: LearningSvg,
    label: LANG_STRINGS.eLearning,
    isVisible: ({ isStaffAgent, agentData, showLms }) =>
      showLms && !isStaffAgent && !checkIsLvAdmin(agentData),
  },
  {
    name: 'profile',
    pathname: '/profile',
    Icon: AgentSvg,
    label: LANG_STRINGS.profile,
  },
]

export const getVisibleBottomTabs = (context) =>
  BOTTOM_TABS.filter((tab) => (tab.isVisible ? tab.isVisible(context) : true))
